// 고른 키워드와 닿은 정도: 직접(main) 5점, 닿은 이야기 2점. 순위·점수는 화면에 보이지 않는다.
export function matchWorks(picks, limit = 12) {
  if (!picks || picks.length === 0) {
    // 아무것도 안 골랐으면 갈래를 고르게 — 키워드마다 한 점씩 돌아가며
    const seen = {};
    const out = [];
    MOCK_WORKS.forEach((w) => { if (!seen[w.main]) { seen[w.main] = true; out.push(w); } });
    const step = Math.max(1, Math.floor(out.length / limit));
    return out.filter((_, i) => i % step === 0).slice(0, limit);
  }
  const scored = MOCK_WORKS.map((w, i) => {
    let s = 0;
    picks.forEach((p) => { if (w.main === p) s += 5; else if (w.tags.includes(p)) s += 2; });
    return { w, s, i };
  }).filter((x) => x.s > 0);
  scored.sort((a, b) => b.s - a.s || ((a.i * 7919) % 97) - ((b.i * 7919) % 97));
  // 같은 물건만 줄줄이 나오지 않게: 먼저 물건마다 한 점씩, 남는 자리에 두 번째
  const per = {};
  const out = [];
  scored.forEach(({ w }) => {
    if (!per[w.item] && out.length < limit) { per[w.item] = 1; out.push(w); }
  });
  scored.forEach(({ w }) => {
    if (out.length < limit && !out.includes(w)) out.push(w);
  });
  return out;
}
